"""Kaggle job: BGE-M3 vs BM25 tool retrieval recall on all train samples (GENERATED by make.py, do not edit by hand).

Flow: unpack the private dataset lifemate-data -> write the embedded scripts into repo/scripts -> run
scripts/retrieval_dense.py (bge-m3 downloaded from Hugging Face, one copy per GPU, texts sharded over both T4s) ->
/kaggle/working/{retrieval_dense.md, bge-m3.dense.npz, run.log}.
"""
import shutil
import subprocess
import sys
import tarfile
from pathlib import Path

WORK = Path("/kaggle/working")
REPO = WORK / "repo"
SCRIPTS = {'retrieval_dense.py': '"""Offline check, dense version: does BGE-M3 retrieval keep the needed tools better than BM25?\n\n  python scripts/retrieval_dense.py --limit 20        # smoke test on the first 20 train samples\n  python scripts/retrieval_dense.py                   # all train samples -> reports/retrieval_dense.md (aggregates only)\n  python scripts/retrieval_dense.py --misses 10       # also print 10 misses of the best app-level config (screen only)\n\nSame candidates and metrics as scripts/retrieval_recall.py (BM25), so the numbers compare one to one:\ncandidates = the tools today\'s prompt gets (installed apps only, sys.* excluded), gold = distinct non-sys gold tools.\nContext ("name + description") is the same for both retrievers:\n  tool doc : tool name split on . and _ + tool description\n  app doc  : app id split on _ + app name_vi + app description\nRetrievers\n  dense    BAAI/bge-m3 dense vector (CLS, L2-normalised, max 512 tokens), cosine query . doc\n  bm25     k1=1.5, b=0.75, IDF over that sample\'s candidates (as in retrieval_recall.py), accents kept\nLevels\n  tool     sample recall@k = share of samples whose gold tools are ALL in the top-k tools\n  app      apps ranked three ways: max or sum of their tools\' scores, or the app doc itself ("app");\n           keep the top-k apps with all their tools, plus contacts when installed (same rule as retrieval_recall.py)\nQuery = normalize_text(final turn), gold transcript or cached PhoWhisper ASR. No history.\nRuns on CUDA when available (Kaggle job kaggle/dense_retrieval/), else CPU; embeddings are cached in work/retrieval/ so a rerun only encodes new texts.\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport hashlib\nimport json\nimport statistics as st\nimport sys\nimport time\nfrom pathlib import Path\n\nimport numpy as np\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nsys.path.insert(0, str(Path(__file__).resolve().parent))\n\nfrom lifemate.data import PROJECT, load_catalog, load_samples  # noqa: E402\nfrom lifemate.normalize import normalize_text  # noqa: E402\nfrom lifemate.prompt import build_prompt  # noqa: E402\nfrom retrieval_recall import bm25, tokens  # noqa: E402\n\nMODEL = "BAAI/bge-m3"\nTOOL_K = [3, 5, 8, 10, 15, 20]\nAPP_K = [1, 2, 3, 4, 5]\nAGGS = ["max", "sum", "app"]\nCACHE = PROJECT / "work" / "retrieval"\nREPORT = PROJECT / "reports" / "retrieval_dense.md"\n\n\nclass Encoder:\n    """bge-m3 dense embeddings with an on-disk cache keyed by the text\'s sha1."""\n\n    def __init__(self, batch: int = 16):\n        self.path = CACHE / "bge-m3.dense.npz"\n        self.vec: dict[str, np.ndarray] = {}\n        if self.path.is_file():\n            z = np.load(self.path)\n            self.vec = dict(zip(z["keys"].tolist(), z["vecs"]))\n        self.batch, self.model, self.tok, self.new = batch, None, None, 0\n\n    @staticmethod\n    def key(t: str) -> str:\n        return hashlib.sha1(t.encode("utf-8")).hexdigest()\n\n    def _load(self) -> None:\n        """One model copy per visible GPU (data sharding, like the Kaggle LLM jobs); CPU when there is none."""\n        import torch\n        from transformers import AutoModel, AutoTokenizer\n        torch.manual_seed(0)\n        self.tok = AutoTokenizer.from_pretrained(MODEL)\n        self.devs = [f"cuda:{i}" for i in range(torch.cuda.device_count())] or ["cpu"]\n        self.models = [AutoModel.from_pretrained(MODEL).eval().to(d) for d in self.devs]\n        print(f"  {MODEL} on {\', \'.join(self.devs)}", flush=True)\n\n    def _run_shard(self, k: int, texts: list[str]) -> list[np.ndarray]:\n        import torch\n        out, t0 = [], time.time()\n        for i in range(0, len(texts), self.batch):\n            enc = self.tok(texts[i:i + self.batch], padding=True, truncation=True, max_length=512, return_tensors="pt").to(self.devs[k])\n            with torch.no_grad():\n                cls = self.models[k](**enc).last_hidden_state[:, 0]\n            out += list(torch.nn.functional.normalize(cls.float(), dim=-1).cpu().numpy().astype(np.float32))\n            if (i // self.batch) % 20 == 0:\n                print(f"  [{self.devs[k]}] {i + self.batch}/{len(texts)} ({time.time() - t0:.0f}s)", flush=True)\n        return out\n\n    def encode(self, texts: list[str]) -> np.ndarray:\n        todo = sorted({t for t in texts if self.key(t) not in self.vec}, key=len)\n        if todo:\n            from concurrent.futures import ThreadPoolExecutor\n            if self.model is None:\n                self._load()\n                self.model = True\n            n = len(self.devs)\n            shards = [todo[k::n] for k in range(n)]  # interleaved so both shards get the same length mix\n            with ThreadPoolExecutor(n) as pool:\n                vecs = list(pool.map(self._run_shard, range(n), shards))\n            for sh, vs in zip(shards, vecs):\n                for t, v in zip(sh, vs):\n                    self.vec[self.key(t)] = v\n            self.new += len(todo)\n            self.save()\n        return np.stack([self.vec[self.key(t)] for t in texts])\n\n    def save(self) -> None:\n        CACHE.mkdir(parents=True, exist_ok=True)\n        keys = list(self.vec)\n        np.savez(self.path, keys=np.array(keys), vecs=np.stack([self.vec[k] for k in keys]))\n\n\ndef tool_doc(t: dict) -> str:\n    f = t["function"]\n    return f"{f[\'name\'].replace(\'.\', \' \').replace(\'_\', \' \')}: {f.get(\'description\', \'\')}"\n\n\ndef app_doc(a: dict) -> str:\n    return f"{a[\'id\'].replace(\'_\', \' \')} {a.get(\'name_vi\', \'\')}: {a.get(\'description\', \'\')}"\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--limit", type=int, default=0, help="first N train samples (smoke test)")\n    ap.add_argument("--misses", type=int, default=0)\n    ap.add_argument("--batch", type=int, default=16)\n    a = ap.parse_args()\n\n    samples = load_samples("train")\n    if a.limit:\n        samples = samples[: a.limit]\n    apps = {x["id"]: x for x in load_catalog("train")["apps"]}\n    asr = {json.loads(l)["audio"]: json.loads(l)["hyp"] for l in (PROJECT / "work/asr/phowhisper/train.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()}\n\n    prep = []\n    for s in samples:\n        tools = [t for t in build_prompt(s, "train", s["audio_text"], None)["tools"] if not t["function"]["name"].startswith("sys.")]\n        gold = {c["name"] for c in s["label"]["tool_calls"] if not c["name"].startswith("sys.")}\n        if gold:\n            prep.append((s, tools, gold))\n    queries = {src: [normalize_text(s["audio_text"] if src == "gold" else asr[s["audio"]]) for s, _, _ in prep] for src in ("gold", "asr")}\n\n    enc = Encoder(a.batch)\n    all_tools = sorted({t["function"]["name"]: t for _, ts, _ in prep for t in ts}.items())\n    t0 = time.time()\n    tvec = dict(zip([n for n, _ in all_tools], enc.encode([tool_doc(t) for _, t in all_tools])))\n    avec = dict(zip(list(apps), enc.encode([app_doc(x) for x in apps.values()])))\n    qvec = {src: enc.encode(q) for src, q in queries.items()}\n    print(f"embeddings ready in {time.time() - t0:.0f}s ({enc.new} newly encoded)")\n\n    results, misses = [], {}\n    for retr in ("dense", "bm25"):\n        for src in ("gold", "asr"):\n            name = f"{retr}, {src}"\n            tool_hits = {k: 0 for k in TOOL_K}\n            app_hits = {(g, k): 0 for g in AGGS for k in APP_K}\n            app_kept = {(g, k): [] for g in AGGS for k in APP_K}\n            miss = {(g, k): [] for g in AGGS for k in APP_K}\n            for i, (s, tools, gold) in enumerate(prep):\n                names = [t["function"]["name"] for t in tools]\n                inst = sorted({nm.split(".")[0] for nm in names})\n                if retr == "dense":\n                    q = qvec[src][i]\n                    sc = [float(q @ tvec[nm]) for nm in names]\n                    app_sc = {x: float(q @ avec[x]) for x in inst}\n                else:\n                    qt = tokens(queries[src][i], False)\n                    sc = bm25(qt, [tokens(tool_doc(t), False) for t in tools])\n                    app_sc = dict(zip(inst, bm25(qt, [tokens(app_doc(apps[x]), False) for x in inst])))\n                order = [names[j] for j in sorted(range(len(names)), key=lambda j: -sc[j])]\n                for k in TOOL_K:\n                    tool_hits[k] += gold <= set(order[:k])\n                by_app: dict[str, list[float]] = {}\n                for nm, x in zip(names, sc):\n                    by_app.setdefault(nm.split(".")[0], []).append(x)\n                for g in AGGS:\n                    key = (lambda x: app_sc[x]) if g == "app" else (lambda x, f=(max if g == "max" else sum): f(by_app[x]))\n                    ranked = sorted(inst, key=lambda x: -key(x))\n                    for k in APP_K:\n                        keep = set(ranked[:k]) | ({"contacts"} & set(inst))\n                        kept = {nm for nm in names if nm.split(".")[0] in keep}\n                        ok = gold <= kept\n                        app_hits[(g, k)] += ok\n                        app_kept[(g, k)].append(len(kept) + 1)\n                        if not ok:\n                            miss[(g, k)].append((s["id"], queries[src][i], sorted(gold - kept)))\n            n = len(prep)\n            results.append({"name": name, "tool": {k: tool_hits[k] / n for k in TOOL_K},\n                            "app": {f"{g}@{k}": (app_hits[(g, k)] / n, st.mean(app_kept[(g, k)])) for g in AGGS for k in APP_K}})\n            misses[name] = miss\n\n    n = len(prep)\n    lines = []\n\n    def out(s: str = "") -> None:\n        print(s)\n        lines.append(s)\n\n    out("# Dense (BGE-M3) vs BM25 tool retrieval: offline recall on train")\n    out()\n    out(f"Generated by `scripts/retrieval_dense.py`. {n} train samples with at least one non-sys gold tool" + (f" (first {a.limit} samples only)" if a.limit else "") + ".")\n    out("Context for both retrievers: tool = name + description, app = id + name_vi + description. Query = normalised final turn, no history.")\n    out(f"Today\'s prompt keeps every installed tool: recall 100%, mean {st.mean(len(t) + 1 for _, t, _ in prep):.1f} tools.")\n    out("BGE-M3 has ~568M parameters: PhoWhisper-large (~1.55B) + Qwen3-4B (~4.02B) + BGE-M3 is ~6.1B, over the 6B system cap, so it is a measurement here, not a deployable choice as is.")\n    out()\n    out("## Tool level: sample recall@k (all gold tools in the top-k tools)")\n    out()\n    out("| retriever / text | " + " | ".join(f"@{k}" for k in TOOL_K) + " |")\n    out("|---|" + "---:|" * len(TOOL_K))\n    for r in results:\n        out(f"| {r[\'name\']} | " + " | ".join(f"{100 * r[\'tool\'][k]:.1f}" for k in TOOL_K) + " |")\n    out()\n    out("## App level: keep the top-k apps (all their tools) + contacts; sample recall % / mean tools kept")\n    out()\n    out("`max` / `sum`: app score from its tools; `app`: score of the app doc itself.")\n    out()\n    for g in AGGS:\n        out(f"| {g} | " + " | ".join(f"@{k}" for k in APP_K) + " |")\n        out("|---|" + "---:|" * len(APP_K))\n        for r in results:\n            out(f"| {r[\'name\']} | " + " | ".join(f"{100 * r[\'app\'][f\'{g}@{k}\'][0]:.1f} / {r[\'app\'][f\'{g}@{k}\'][1]:.1f}" for k in APP_K) + " |")\n        out()\n    out("## Verdict (ASR text, what the pipeline sees)")\n    out()\n    for retr in ("dense", "bm25"):\n        r = next(x for x in results if x["name"] == f"{retr}, asr")\n        bt = max(TOOL_K, key=lambda k: (r["tool"][k], -k))\n        ba = max(r["app"], key=lambda x: (r["app"][x][0], -r["app"][x][1]))\n        out(f"- {retr}: best tool level @{bt} {100 * r[\'tool\'][bt]:.1f}%; best app level {ba} {100 * r[\'app\'][ba][0]:.1f}% keeping {r[\'app\'][ba][1]:.1f} tools.")\n    d, b = (next(x for x in results if x["name"] == f"{m}, asr") for m in ("dense", "bm25"))\n    gains = [100 * (d["app"][x][0] - b["app"][x][0]) for x in d["app"]]\n    out(f"- dense minus BM25 over all app-level settings: {min(gains):+.1f} to {max(gains):+.1f} points; tool level @10 {100 * (d[\'tool\'][10] - b[\'tool\'][10]):+.1f}, @20 {100 * (d[\'tool\'][20] - b[\'tool\'][20]):+.1f}.")\n    best = max(d["app"].values(), key=lambda v: v[0])[0]\n    out(f"- A filter is safe only near 100% recall (a dropped tool makes the sample score 0): best dense app-level recall is {100 * best:.1f}%, {\'safe\' if best >= 0.99 else \'not safe\'}.")\n    if not a.limit:\n        REPORT.write_text("\\n".join(lines) + "\\n", encoding="utf-8")\n        print(f"-> {REPORT}")\n    if a.misses:\n        ba = max(d["app"], key=lambda x: (d["app"][x][0], -d["app"][x][1]))\n        g, k = ba.split("@")\n        m = misses["dense, asr"][(g, int(k))]\n        print(f"\\n(screen only) {min(a.misses, len(m))} of {len(m)} misses of dense, asr {ba}:")\n        for sid, q, gone in m[: a.misses]:\n            print(f"  {sid} | {q} | missing {\', \'.join(gone)}")\n\n\nif __name__ == "__main__":\n    main()\n', 'retrieval_recall.py': '"""Offline check: could BM25 retrieval shrink the tool list in the LifeMate prompt without dropping a needed tool?\n\n  python scripts/retrieval_recall.py                      # all train samples, every config, table + reports/retrieval_bm25.md\n  python scripts/retrieval_recall.py --misses 20          # list more misses of the best app-level config\n\nNo model, stdlib only, local CPU. Candidates per sample = exactly the tools the prompt gets today\n(lifemate.prompt.build_prompt(...)["tools"], installed apps only, sys.* excluded from ranking: sys.ask_missing_info\nstays in the prompt anyway). Gold tools = distinct non-sys names in label.tool_calls.\n\nBM25 (k1=1.5, b=0.75) over one document per candidate tool, IDF computed over that sample\'s candidates.\n  doc "desc"   : tool name split on . and _, app id, app name_vi + description (catalog), tool description\n  doc "params" : "desc" + parameter names and parameter descriptions\n  tokens       : lowercase + NFC, split on non-word characters; "noacc" variant also strips Vietnamese accents (đ -> d)\n  query        : normalize_text(final turn), text = gold (audio_text) or asr (cached PhoWhisper hyp);\n                 "+hist" appends the history user turns (same text source)\nMetrics\n  tool level : sample recall@k = share of samples (with >= 1 gold tool) whose gold tools are ALL in the top-k tools;\n               call recall@k = share of gold (sample, tool) pairs in the top-k\n  app level  : app score = max (or sum) BM25 of its tools; keep the top-k apps with ALL their tools, plus contacts when\n               installed; sample recall and tools kept (mean / median), against today\'s prompt (all tools)\n"""\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport math\nimport re\nimport statistics as st\nimport sys\nimport unicodedata\nfrom collections import Counter\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\n\nfrom lifemate.data import PROJECT, load_catalog, load_samples  # noqa: E402\nfrom lifemate.normalize import normalize_text  # noqa: E402\nfrom lifemate.prompt import build_prompt  # noqa: E402\n\nK1, B = 1.5, 0.75\nTOOL_K = [3, 5, 8, 10, 15, 20]\nAPP_K = [1, 2, 3, 4]\nREPORT = PROJECT / "reports" / "retrieval_bm25.md"\n\n\ndef strip_accents(s: str) -> str:\n    s = s.replace("đ", "d").replace("Đ", "D")\n    return "".join(c for c in unicodedata.normalize("NFD", s) if unicodedata.category(c) != "Mn")\n\n\ndef tokens(s: str, noacc: bool) -> list[str]:\n    s = unicodedata.normalize("NFC", s.lower())\n    if noacc:\n        s = strip_accents(s)\n    return [t for t in re.split(r"[\\W_]+", s) if t]\n\n\ndef tool_doc(t: dict, apps: dict, with_params: bool) -> str:\n    f = t["function"]\n    app = f["name"].split(".")[0]\n    a = apps.get(app, {})\n    parts = [f["name"].replace(".", " ").replace("_", " "), app.replace("_", " "), a.get("name_vi", ""), a.get("description", ""), f.get("description", "")]\n    if with_params:\n        for k, p in (f.get("parameters", {}).get("properties") or {}).items():\n            parts += [k.replace("_", " "), p.get("description", "")]\n    return " ".join(parts)\n\n\ndef bm25(query: list[str], docs: list[list[str]]) -> list[float]:\n    n = len(docs)\n    avg = sum(map(len, docs)) / n\n    df = Counter(t for d in docs for t in set(d))\n    q = Counter(query)\n    out = []\n    for d in docs:\n        tf = Counter(d)\n        s = 0.0\n        for t in q:\n            if t in tf:\n                idf = math.log(1 + (n - df[t] + 0.5) / (df[t] + 0.5))\n                s += idf * tf[t] * (K1 + 1) / (tf[t] + K1 * (1 - B + B * len(d) / avg))\n        out.append(s)\n    return out\n\n\ndef main() -> None:\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--misses", type=int, default=10)\n    a = ap.parse_args()\n\n    samples = load_samples("train")\n    apps = {x["id"]: x for x in load_catalog("train")["apps"]}\n    asr = {json.loads(l)["audio"]: json.loads(l)["hyp"] for l in (PROJECT / "work/asr/phowhisper/train.jsonl").read_text(encoding="utf-8").splitlines() if l.strip()}\n\n    prep = []  # (sample, candidate tool dicts, gold tool names)\n    for s in samples:\n        tools = [t for t in build_prompt(s, "train", s["audio_text"], None)["tools"] if not t["function"]["name"].startswith("sys.")]\n        gold = {c["name"] for c in s["label"]["tool_calls"] if not c["name"].startswith("sys.")}\n        prep.append((s, tools, gold))\n    n_all = len(prep)\n    with_gold = [p for p in prep if p[2]]\n    n_tools_today = [len(t) + 1 for _, t, _ in prep]  # + sys.ask_missing_info\n    missing_cand = sum(1 for _, t, g in with_gold if not g <= {x["function"]["name"] for x in t})\n\n    def query_text(s: dict, src: str, hist: bool) -> str:\n        final = s["audio_text"] if src == "gold" else asr[s["audio"]]\n        parts = [final]\n        if hist:\n            for h in s["history"]:\n                if h["role"] == "user":\n                    parts.append(h.get("audio_text") if src == "gold" else asr.get(h["audio"], h.get("audio_text", "")) or "")\n        return normalize_text(" ".join(p for p in parts if p))\n\n    results = []  # dict per config\n    examples = {}\n    for src in ("gold", "asr"):\n        for hist in (False, True):\n            for doc_kind in ("desc", "params"):\n                for noacc in (False, True):\n                    name = f"{src}{\'+hist\' if hist else \'\'} | {doc_kind} | {\'noacc\' if noacc else \'acc\'}"\n                    tool_hits = {k: 0 for k in TOOL_K}\n                    call_hits = {k: 0 for k in TOOL_K}\n                    n_calls = 0\n                    app_hits = {(agg, k): 0 for agg in ("max", "sum") for k in APP_K}\n                    app_kept = {(agg, k): [] for agg in ("max", "sum") for k in APP_K}\n                    misses = {(agg, k): [] for agg in ("max", "sum") for k in APP_K}\n                    for s, tools, gold in with_gold:\n                        names = [t["function"]["name"] for t in tools]\n                        sc = bm25(tokens(query_text(s, src, hist), noacc), [tokens(tool_doc(t, apps, doc_kind == "params"), noacc) for t in tools])\n                        order = [names[i] for i in sorted(range(len(names)), key=lambda i: -sc[i])]\n                        n_calls += len(gold)\n                        for k in TOOL_K:\n                            top = set(order[:k])\n                            tool_hits[k] += gold <= top\n                            call_hits[k] += len(gold & top)\n                        by_app: dict[str, list[float]] = {}\n                        for nm, x in zip(names, sc):\n                            by_app.setdefault(nm.split(".")[0], []).append(x)\n                        for agg in ("max", "sum"):\n                            ranked = sorted(by_app, key=lambda ap_: -(max if agg == "max" else sum)(by_app[ap_]))\n                            for k in APP_K:\n                                keep = set(ranked[:k]) | ({"contacts"} & set(by_app))\n                                kept = {nm for nm in names if nm.split(".")[0] in keep}\n                                ok = gold <= kept\n                                app_hits[(agg, k)] += ok\n                                app_kept[(agg, k)].append(len(kept) + 1)\n                                if not ok:\n                                    misses[(agg, k)].append((s["id"], query_text(s, src, False), sorted(gold - kept)))\n                    n = len(with_gold)\n                    r = {"name": name, "tool": {k: tool_hits[k] / n for k in TOOL_K}, "call": {k: call_hits[k] / n_calls for k in TOOL_K},\n                         "app": {f"{agg}@{k}": (app_hits[(agg, k)] / n, st.mean(app_kept[(agg, k)]), st.median(app_kept[(agg, k)])) for agg in ("max", "sum") for k in APP_K}}\n                    results.append(r)\n                    examples[name] = misses\n\n    n = len(with_gold)\n    lines = []\n\n    def out(s: str = "") -> None:\n        print(s)\n        lines.append(s)\n\n    out("# BM25 tool retrieval: offline recall on train")\n    out()\n    out(f"Train samples: {n_all}; with at least one non-sys gold tool: {n}; without (gold empty or only sys.ask_missing_info): {n_all - n}.")\n    out(f"Samples whose gold tool is not among today\'s candidates at all: {missing_cand}.")\n    out(f"Before (all tools, today\'s prompt): sample recall 100% by construction, tools per prompt mean {st.mean(n_tools_today):.1f}, median {st.median(n_tools_today):.0f} (incl. sys.ask_missing_info).")\n    out()\n    out("## Tool level: sample recall@k (all gold tools in top-k)")\n    out()\n    out("| config | " + " | ".join(f"@{k}" for k in TOOL_K) + " | call recall@10 |")\n    out("|---|" + "---|" * (len(TOOL_K) + 1))\n    for r in results:\n        out(f"| {r[\'name\']} | " + " | ".join(f"{100 * r[\'tool\'][k]:.1f}" for k in TOOL_K) + f" | {100 * r[\'call\'][10]:.1f} |")\n    out()\n    out("## App level: keep top-k apps (all their tools) + contacts; sample recall % / mean tools kept / median tools kept")\n    out()\n    keys = [f"{agg}@{k}" for agg in ("max", "sum") for k in APP_K]\n    out("| config | " + " | ".join(keys) + " |")\n    out("|---|" + "---|" * len(keys))\n    for r in results:\n        out(f"| {r[\'name\']} | " + " | ".join(f"{100 * r[\'app\'][x][0]:.1f} / {r[\'app\'][x][1]:.1f} / {r[\'app\'][x][2]:.0f}" for x in keys) + " |")\n    out()\n\n    # best app-level config on ASR text (what the pipeline will see): smallest k reaching >= 99%, then fewest tools kept\n    asr_results = [r for r in results if r["name"].startswith("asr")]\n    cands = [(r, x) for r in asr_results for x in keys if r["app"][x][0] >= 0.99]\n    out("## Verdict")\n    out()\n    if cands:\n        r, x = min(cands, key=lambda c: (c[0]["app"][c[1]][1], -c[0]["app"][c[1]][0]))\n    else:\n        r, x = max(((r, x) for r in asr_results for x in keys), key=lambda c: (c[0]["app"][c[1]][0], -c[0]["app"][c[1]][1]))\n    rec, mean_k, med_k = r["app"][x]\n    best_tool = max(((rr, k) for rr in asr_results for k in TOOL_K), key=lambda c: (c[0]["tool"][c[1]], -c[1]))\n    gold_side = [rr for rr in results if rr["name"] == r["name"].replace("asr", "gold", 1)][0]\n    out(f"Best app-level config on ASR text: {r[\'name\']}, {x}: sample recall {100 * rec:.1f}%, tools kept mean {mean_k:.1f}, median {med_k:.0f} (today median {st.median(n_tools_today):.0f}).")\n    out(f"Same config on the reference transcript: sample recall {100 * gold_side[\'app\'][x][0]:.1f}%.")\n    out(f"{\'It reaches\' if rec >= 0.99 else \'No app-level config reaches\'} the 99% sample-recall bar{\' \' if rec >= 0.99 else \' on ASR text; the best one is shown\'}.")\n    out(f"Verdict: BM25 app-level retrieval is {\'safe at this setting\' if rec >= 0.99 else \'NOT safe\'}: "\n        f"{\'\' if rec >= 0.99 else f\'it drops a needed tool in {100 * (1 - rec):.1f}% of samples, and each such sample scores 0\'}.")\n    out(f"Tool-level top-k is weaker: best on ASR text is {best_tool[0][\'name\']} @{best_tool[1]} with {100 * best_tool[0][\'tool\'][best_tool[1]]:.1f}% sample recall; top-3 and top-5 miss far more.")\n    miss = examples[r["name"]][(x.split("@")[0], int(x.split("@")[1]))]\n    missed = Counter(t for _, _, m in miss for t in m)\n    out(f"Misses of the best config: {len(miss)} of {n} samples. Most often missing gold tools: "\n        + ", ".join(f"`{t}` {c}" for t, c in missed.most_common(8)) + ".")\n    out("Per-sample misses (ids and queries) are printed to the screen only: the repo is public.")\n    REPORT.parent.mkdir(exist_ok=True)\n    REPORT.write_text("\\n".join(lines) + "\\n", encoding="utf-8")\n    print(f"\\n(screen only) first {min(a.misses, len(miss))} misses of the best config:")\n    for sid, q, m in miss[: a.misses]:\n        print(f"  {sid} | {q} | missing {\', \'.join(m)}")\n    print(f"-> {REPORT}")\n\n\nif __name__ == "__main__":\n    main()\n'}

